PLATFORM_PASSWORD_RESET_EXPIRE_MINUTES = 30


def get_global_maintenance_mode(db: Session) -> bool:
    setting = db.query(PlatformSetting).filter(PlatformSetting.key == GLOBAL_MAINTENANCE_KEY).first()
    return bool(setting.value_bool) if setting else False


