def seed_default_features(db: Session) -> None:
    """Upsert canonical features; also updates display name / module on existing rows."""
    for key, name, module, description in DEFAULT_PLATFORM_FEATURES:
        row = db.query(Feature).filter(Feature.key == key).first()
        if row:
            # Keep display names and module grouping in sync with the canonical list
            row.name = name
            row.module = module
            if description:
                row.description = description
        else:
            db.add(Feature(key=key, name=name, module=module, description=description))
    db.flush()


# Dashboard tabs added with prototype v17 (Deals, Orders & delivery, Finance). Sub-feature permissions are only kept for a
# tenant when its plan / tenant features list them, so each is entitled once wherever the plan or tenant already has the
# data the tab shows. Later changes made in the platform console are kept (a marker per tab stops this from re-running).
NEW_DASHBOARD_TAB_FEATURES = {
    "dashboard.deals.view": ("dashboard.view", "opportunities.view"),
    "dashboard.orders.view": ("dashboard.view", "workorders.view"),
    "dashboard.finance.view": ("dashboard.emdbg.view",),   # Finance replaces the EMD / BG dashboard
}


def entitle_new_dashboard_tabs(db: Session) -> None:
    from app.models.tenant import PlanFeature, TenantFeature
    feats = {f.key: f for f in db.query(Feature).filter(Feature.key.in_(
        list(NEW_DASHBOARD_TAB_FEATURES) + [k for req in NEW_DASHBOARD_TAB_FEATURES.values() for k in req])).all()}
    for key, req in NEW_DASHBOARD_TAB_FEATURES.items():
        marker = f"entitled:{key}"
        if key not in feats or any(r not in feats for r in req) or db.query(PlatformSetting).filter(PlatformSetting.key == marker).first():
            continue
        new_id, req_ids = feats[key].id, [feats[r].id for r in req]
        for Model, col in ((PlanFeature, "plan_id"), (TenantFeature, "tenant_id")):
            owner = getattr(Model, col)
            holders = None
            for rid in req_ids:
                ids = {o for (o,) in db.query(owner).filter(Model.feature_id == rid, Model.enabled == True).all()}
                holders = ids if holders is None else holders & ids
            for oid in sorted(holders or ()):
                row = db.query(Model).filter(owner == oid, Model.feature_id == new_id).first()
                if row is None:
                    db.add(Model(**{col: oid, "feature_id": new_id, "enabled": True}))
                elif not row.enabled:
                    row.enabled = True
        db.add(PlatformSetting(key=marker, value_bool=True))
    db.flush()


def migrate_legacy_feature_keys(db: Session) -> None:
    """Rename or remove old-style feature keys (underscores, no dots)."""
    for old_key, new_key in LEGACY_FEATURE_KEY_RENAMES.items():
        old_row = db.query(Feature).filter(Feature.key == old_key).first()
        if not old_row:
            continue
        new_row = db.query(Feature).filter(Feature.key == new_key).first()
        if new_row:
            # New canonical key already exists; preserve old assignments before deleting it.
            old_plan_features = db.query(PlanFeature).filter(PlanFeature.feature_id == old_row.id).all()
            for old_plan_feature in old_plan_features:
                existing = db.query(PlanFeature).filter(
                    PlanFeature.plan_id == old_plan_feature.plan_id,
                    PlanFeature.feature_id == new_row.id,
                ).first()
                if existing:
                    existing.enabled = bool(existing.enabled or old_plan_feature.enabled)
                    db.delete(old_plan_feature)
                else:
                    old_plan_feature.feature_id = new_row.id

            old_tenant_features = db.query(TenantFeature).filter(TenantFeature.feature_id == old_row.id).all()
            for old_tenant_feature in old_tenant_features:
                existing = db.query(TenantFeature).filter(
                    TenantFeature.tenant_id == old_tenant_feature.tenant_id,
                    TenantFeature.feature_id == new_row.id,
                ).first()
                if existing:
                    existing.enabled = bool(existing.enabled or old_tenant_feature.enabled)
                    if not existing.source and old_tenant_feature.source:
                        existing.source = old_tenant_feature.source
                    db.delete(old_tenant_feature)
                else:
                    old_tenant_feature.feature_id = new_row.id
            db.delete(old_row)
        else:
            # Rename in-place so existing plan/tenant assignments carry over
            old_row.key = new_key
        db.flush()


def _write_platform_audit(
    db: Session,
    admin: Optional[SuperAdmin],
    action: str,
    entity_type: str,
    entity_id: Optional[int],
    entity_name: Optional[str],
    description: str,
    ip: str = "system",
    old_data: Optional[dict] = None,
    new_data: Optional[dict] = None,
) -> None:
    try:
        db.add(PlatformAuditLog(
            super_admin_id=admin.id if admin else None,
            action=action,
            entity_type=entity_type,
            entity_id=entity_id,
            entity_name=entity_name,
            old_data=old_data,
            new_data=new_data,
            description=description,
            ip_address=ip,
        ))
        db.flush()
    except Exception as exc:
        logger.error("Failed to write platform audit log: %s", exc)


def _get_platform_admin(request: Request) -> Optional[SuperAdmin]:
    return getattr(request.state, "platform_admin", None)


# Sensitive actions that need a second staff member's approval while four-eyes
# is on: action -> (module the approver must manage, Super admin approver only).
FOUR_EYES_ACTIONS = {
    "suspend_tenant": ("tenants", False),
    "update_global_maintenance": ("settings", False),
    "delete_plan": ("billing", False),
    "deactivate_super_admin": ("team", False),
    "assign_staff_access": ("team", False),
    "update_role_permissions": ("team", True),
    "disable_four_eyes": ("team", False),
    # Change & maintenance: every scheduled change is approved here, whether or not four-eyes is on.
    "approve_change": ("changes", False),
    # Environments & sandboxes: promoting a change set to production while "Change-set promotion needs approval" is on.
    "promote_change_set": ("databases", False),
    # Trust & Safety: tenant enforcement (gated when four-eyes is on) and acceptable-use policy actions (always reviewed).
    "ts_suspend_tenant": ("tenants", False),
    "ts_terminate_tenant": ("tenants", False),
    "ts_warn_tenant": ("tenants", False),
}


def _approval_dict(row: PlatformApprovalRequest) -> dict:
    return {"approval_required": True, "request_id": row.id, "message": f"Sent for approval as request #{row.id}. Another staff member must approve it before it takes effect."}


def _four_eyes_gate(
    db: Session,
    request: Request,
    action: str,
    entity_type: str,
    entity_id: Optional[int],
    entity_name: Optional[str],
    summary: str,
    payload: Optional[dict] = None,
) -> Optional[JSONResponse]:
    """Queue the action for approval and return a 202 response, or None to run it now."""
    if getattr(request.state, "four_eyes_approved", False) or not access_control.four_eyes_enabled(db):
        return None
    module, _ = FOUR_EYES_ACTIONS[action]
    pending = db.query(PlatformApprovalRequest).filter(
        PlatformApprovalRequest.action == action,
        PlatformApprovalRequest.entity_type == entity_type,
        PlatformApprovalRequest.entity_id.is_(None) if entity_id is None else PlatformApprovalRequest.entity_id == entity_id,
        PlatformApprovalRequest.status == "pending",
    ).first()
    if pending:
        if (pending.payload or {}) == (payload or {}):
            return JSONResponse(status_code=202, content=_approval_dict(pending))
        raise HTTPException(status_code=409, detail=f"Request #{pending.id} for this is already waiting for approval.")
    admin = _get_platform_admin(request)
    row = PlatformApprovalRequest(
        action=action, module=module, entity_type=entity_type, entity_id=entity_id,
        entity_name=entity_name, summary=summary[:500], payload=payload or {},
        status="pending", requested_by=admin.id if admin else None,
    )
    db.add(row)
    db.flush()
    _write_platform_audit(
        db, admin, "request_approval", "approval_request", row.id, entity_name,
        f"Requested approval #{row.id}: {summary}", get_request_ip(request),
        new_data={"action": action, "payload": payload or {}},
    )
    db.commit()
    return JSONResponse(status_code=202, content=_approval_dict(row))


