class FeatureCreate(BaseModel):
    key: str
    name: str
    module: Optional[str] = None
    description: Optional[str] = None


class PlanFeatureUpdate(BaseModel):
    feature_ids: list[int]


class PlanFeatureResponse(BaseModel):
    plan_id: int
    feature_ids: list[int]


class PlatformLoginRequest(BaseModel):
    username: str
    password: str
    new_password: Optional[str] = None  # ignored; use /login/change-password
    device_id: Optional[str] = None
    captcha_id: Optional[str] = None
    captcha_answer: Optional[str] = None


class PlatformLoginStepRequest(BaseModel):
    challenge_id: str
    device_id: Optional[str] = None


class PlatformVerifyOtpRequest(PlatformLoginStepRequest):
    otp: str
    trust_device: bool = False          # "Trust this device for 30 days" (opt-in)


class PlatformLoginPasswordChangeRequest(PlatformLoginStepRequest):
    new_password: str
    trust_device: bool = False          # carried from the OTP step when the sign-in had one


class PlatformLoginSecurityUpdate(BaseModel):
    otp_mode: Optional[str] = None
    captcha_mode: Optional[str] = None


class PlatformForgotPasswordRequest(BaseModel):
    email: str = Field(..., min_length=1, max_length=255)   # the account's e-mail or user name


class PlatformContactAdminRequest(BaseModel):
    contact: str = Field(..., min_length=1, max_length=200)
    category: str = Field(..., max_length=60)
    message: str = Field("", max_length=2000)


class PlatformResetPasswordRequest(BaseModel):
    token: str
    new_password: str
    confirm_password: str


class PlatformChangePasswordRequest(BaseModel):
    current_password: str
    new_password: str
    confirm_password: str


class GlobalMaintenanceUpdate(BaseModel):
    enabled: bool


class TenantAdditionalUser(BaseModel):
    full_name: str
    email: EmailStr
    username: str
    password: str
    role: str = "admin"

    @field_validator("username")
    @classmethod
    def validate_username(cls, value: str) -> str:
        normalized = value.strip().lower()
        if not normalized or len(normalized) > 50:
            raise ValueError("Username must contain 1 to 50 characters")
        return normalized


class TenantCreate(BaseModel):
    name: str
    slug: str
    subdomain: str
    admin_email: EmailStr
    admin_name: str
    admin_password: str
    plan_id: Optional[int] = None
    max_users: int = 5
    normal_login_expiry_minutes: int = DEFAULT_NORMAL_LOGIN_EXPIRY_MINUTES
    remember_me_expiry_minutes: int = DEFAULT_REMEMBER_ME_EXPIRY_MINUTES
    inactivity_timeout_minutes: int = 30
    session_warning_minutes: int = 5
    smtp_host: Optional[str] = None
    smtp_port: Optional[int] = None
    smtp_user: Optional[str] = None
    smtp_password: Optional[str] = None
    smtp_use_tls: bool = True
    smtp_use_ssl: bool = False
    from_email: Optional[EmailStr] = None
