def _platform_setting(db: Session, key: str, default: bool = False) -> bool:
    row = db.query(PlatformSetting).filter(PlatformSetting.key == key).first()
    return bool(row.value_bool) if row else default


def _send_platform_device_alert(admin: SuperAdmin, request: Request) -> None:
    if not (settings.SMTP_HOST and settings.SMTP_USER and settings.SMTP_PASSWORD):
        raise RuntimeError("Platform SMTP is not configured")
    message = EmailMessage()
    message["Subject"] = "New device sign-in to your platform account"
    message["From"] = settings.EMAILS_FROM or settings.SMTP_USER
    message["To"] = admin.email
    message.set_content(f"Hello {admin.full_name},\n\nYour platform account signed in from a new browser or device.\nIP address: {get_request_ip(request)}\nBrowser: {request.headers.get('user-agent', 'Unknown')}\n\nIf this was not you, change your password and contact your administrator.")
    with smtplib.SMTP(settings.SMTP_HOST, int(settings.SMTP_PORT), timeout=30) as server:
        server.starttls(context=ssl.create_default_context())
        server.login(settings.SMTP_USER, settings.SMTP_PASSWORD)
        server.send_message(message)


def _platform_device_key(admin_id: int, device_hash: str) -> str:
    return f"platform_device_{admin_id}_{device_hash}"


def _is_known_platform_device(db: Session, admin: Optional[SuperAdmin], device_hash: Optional[str]) -> bool:
    """Trusted for 30 days (platform_trusted_devices), or remembered before expiry existed (legacy key, migrated on its next sign-in)."""
    if not admin or not device_hash:
        return False
    if login_security.device_trusted(db, admin.id, device_hash):
        return True
    return db.query(PlatformSetting).filter(PlatformSetting.key == _platform_device_key(admin.id, device_hash)).first() is not None


def _password_policy_error(db: Session, admin: Optional[SuperAdmin], password: str) -> Optional[str]:
    """Control Center → Authentication policy (length, history) for a platform staff password; None when it passes."""
    from app.services import platform_password_policy
    try:
        platform_password_policy.check(db, admin, password)
    except platform_password_policy.PasswordPolicyError as exc:
        return str(exc)
    return None


def _record_password(db: Session, admin: SuperAdmin) -> None:
    from app.services import platform_password_policy
    platform_password_policy.record(db, admin)


def _pending_first_change(db: Session, admin: SuperAdmin) -> Optional[PlatformSetting]:
    row = db.query(PlatformSetting).filter(PlatformSetting.key == f"platform_first_change_{admin.id}").first()
    return row if row and row.value_bool else None


def _login_security_http_error(db: Session, exc: "login_security.LoginSecurityError") -> HTTPException:
    # Persist attempt counters / consumed challenges before failing the request.
    db.commit()
    headers = {"Retry-After": str(exc.extra["retry_after"])} if "retry_after" in exc.extra else None
    return HTTPException(status_code=exc.status_code, detail=exc.detail(), headers=headers)


def _finish_platform_login(db: Session, admin: SuperAdmin, device_hash: Optional[str], request: Request, trust: Optional[bool] = None) -> dict:
    """The only place a platform session / token is issued.

    ``trust``: the "Trust this device for 30 days" choice of a sign-in that had an OTP step (None = no OTP step: the
    device is remembered as before, now for 30 days). A trusted device's 30 days restart on every sign-in."""
    known = _is_known_platform_device(db, admin, device_hash)
    if device_hash:
        db.query(PlatformSetting).filter(PlatformSetting.key == _platform_device_key(admin.id, device_hash)).delete()   # legacy, never-expiring
        if trust is False:
            login_security.forget_device(db, admin.id, device_hash)
        else:
            login_security.trust_device(db, admin.id, device_hash)
    if device_hash and not known:
        if _platform_setting(db, "platform_new_device_alert", False):
            try:
                _send_platform_device_alert(admin, request)
            except Exception:
                logger.exception("Could not send platform new device alert for account %s", admin.id)
    login_security.clear_failures(db, admin.username)
    _write_platform_audit(db, admin, "platform_login", "super_admin", admin.id, admin.username, "Signed in to the platform", get_request_ip(request))
    session_id = secrets.token_urlsafe(32)
    db.add(PlatformSession(id=session_id, admin_id=admin.id, last_active=datetime.utcnow(), is_active=True))
    db.commit()
    token = create_access_token(admin.id, session_jti=session_id)
    return {
        "access_token": token,
        "token_type": "bearer",
        "role": "super_admin",
        "full_name": admin.full_name,
        "username": admin.username,
    }


def _challenge_response(challenge, admin: SuperAdmin, policy) -> dict:
    body = {
        "challenge_id": challenge.id,
        "otp_required": bool(challenge.otp_required and not challenge.otp_verified),
        "password_change_required": bool(challenge.password_change_required),
    }
    if body["otp_required"]:
        body.update(login_security.otp_status(challenge, admin, policy))
    return body


def _challenge_admin(db: Session, challenge) -> SuperAdmin:
    admin = db.query(SuperAdmin).filter(SuperAdmin.id == challenge.admin_id, SuperAdmin.is_active == True).first()
    if not admin:
        login_security.consume(db, challenge)
        db.commit()
        raise HTTPException(status_code=401, detail={"code": "login_expired", "message": "Your sign-in session has expired. Please sign in again."})
    return admin


@router.post("/login/captcha")
def platform_login_captcha(request: Request, db: Session = Depends(get_master_db_dep)):
    captcha = login_security.create_captcha(db, get_request_ip(request))
    db.commit()
    return captcha


def _audit_sign_in_attempt(db: Session, username: str, ip: str, action: str, description: str) -> None:
    """Failed or blocked platform sign-in in the audit trail (the attempted username and IP – never the password)."""
    account = db.query(SuperAdmin).filter(SuperAdmin.username == username).first() if username else None
    _write_platform_audit(db, None, action, "super_admin", account.id if account else None, (username or "")[:100] or None, description, ip)
    if action == "platform_login_blocked":   # the caller raises without committing
        db.commit()


@router.post("/login")
def platform_login(data: PlatformLoginRequest, request: Request, db: Session = Depends(get_master_db_dep)):
    ip = get_request_ip(request)
    username = (data.username or "").strip()
    policy = login_security.get_policy(db)

    remaining = login_security.lockout_remaining_seconds(db, username, ip)
    if remaining:
        _audit_sign_in_attempt(db, username, ip, "platform_login_blocked", f"Platform sign-in blocked for '{username[:100]}': locked for {remaining} more seconds")
        raise HTTPException(
            status_code=429,
            detail={"code": "locked", "message": f"Too many failed attempts. Try again in {remaining} seconds.", "retry_after": remaining},
            headers={"Retry-After": str(remaining)},
        )

    device_hash = login_security.hash_device(data.device_id)
    admin = db.query(SuperAdmin).filter(SuperAdmin.username == username, SuperAdmin.is_active == True).first()
    known_device = _is_known_platform_device(db, admin, device_hash)

    # CAPTCHA is decided without revealing whether the username exists.
    if login_security.captcha_required(policy, db, username, known_device):
        if not data.captcha_id or not data.captcha_answer:
            db.commit()
            raise HTTPException(status_code=400, detail={"code": "captcha_required", "message": "Please complete the CAPTCHA to continue.", "captcha_required": True})
        if not login_security.verify_captcha(db, data.captcha_id, data.captcha_answer):
            login_security.record_failure(db, username, ip)
            _audit_sign_in_attempt(db, username, ip, "platform_login_failed", f"Platform sign-in failed for '{username[:100]}': CAPTCHA incorrect or expired")
            db.commit()
            raise HTTPException(status_code=400, detail={"code": "captcha_invalid", "message": "The CAPTCHA answer was incorrect or has expired. Try a new one.", "captcha_required": True})

    if not admin or not verify_password(data.password, admin.hashed_password):
        login_security.record_failure(db, username, ip)
        _audit_sign_in_attempt(db, username, ip, "platform_login_failed",
                               f"Platform sign-in failed for '{username[:100]}': {'wrong password' if admin else 'unknown or inactive account'}")
        captcha_next = login_security.captcha_required(policy, db, username, known_device)
        db.commit()
        raise HTTPException(status_code=401, detail={"code": "invalid_credentials", "message": "Invalid platform credentials", "captcha_required": captcha_next})

    from app.services import platform_password_policy
    try:
        if _pending_first_change(db, admin) is None and platform_password_policy.rotation_due(db, admin):
            platform_password_policy.require_change(db, admin)
            db.flush()
    except Exception:  # noqa: BLE001 - an unreadable rotation setting must not block sign-in
        logger.exception("Password rotation check failed for platform account %s", admin.id)
    need_otp = login_security.otp_required(policy, known_device)
    need_password_change = _pending_first_change(db, admin) is not None
    if not need_otp and not need_password_change:
        return _finish_platform_login(db, admin, device_hash, request)

    try:
        challenge = login_security.start_login_challenge(
            db, admin, policy, need_otp=need_otp, need_password_change=need_password_change,
            device_hash=device_hash, ip=ip,
        )
    except login_security.LoginSecurityError as exc:
        raise _login_security_http_error(db, exc)
    _write_platform_audit(db, admin, "platform_login_challenge", "super_admin", admin.id, admin.username,
                          "Password accepted; additional verification required", ip,
                          new_data={"otp_required": need_otp, "password_change_required": need_password_change})
    db.commit()
    return _challenge_response(challenge, admin, policy)


@router.post("/login/verify-otp")
def platform_login_verify_otp(data: PlatformVerifyOtpRequest, request: Request, db: Session = Depends(get_master_db_dep)):
    policy = login_security.get_policy(db)
    device_hash = login_security.hash_device(data.device_id)
    try:
        challenge = login_security.load_login_challenge(db, data.challenge_id, device_hash)
        admin = _challenge_admin(db, challenge)
        try:
            login_security.verify_otp(db, challenge, policy, data.otp)
        except login_security.LoginSecurityError as exc:
            if exc.code in ("otp_invalid", "otp_locked"):
                login_security.record_failure(db, admin.username, get_request_ip(request))
            raise
    except login_security.LoginSecurityError as exc:
        raise _login_security_http_error(db, exc)

    if login_security.ready_for_session(challenge):
        login_security.consume(db, challenge)
        return _finish_platform_login(db, admin, device_hash, request, trust=data.trust_device)
    db.commit()
    return _challenge_response(challenge, admin, policy)


@router.post("/login/resend-otp")
def platform_login_resend_otp(data: PlatformLoginStepRequest, db: Session = Depends(get_master_db_dep)):
    policy = login_security.get_policy(db)
    try:
        challenge = login_security.load_login_challenge(db, data.challenge_id, login_security.hash_device(data.device_id))
        admin = _challenge_admin(db, challenge)
        login_security.resend_otp(db, challenge, admin, policy)
    except login_security.LoginSecurityError as exc:
        raise _login_security_http_error(db, exc)
    db.commit()
    return _challenge_response(challenge, admin, policy)


@router.post("/login/change-password")
def platform_login_change_password(data: PlatformLoginPasswordChangeRequest, request: Request, db: Session = Depends(get_master_db_dep)):
    device_hash = login_security.hash_device(data.device_id)
    try:
        challenge = login_security.load_login_challenge(db, data.challenge_id, device_hash)
    except login_security.LoginSecurityError as exc:
        raise _login_security_http_error(db, exc)
    admin = _challenge_admin(db, challenge)
    if challenge.otp_required and not challenge.otp_verified:
        raise HTTPException(status_code=403, detail={"code": "otp_required", "message": "Verify the code sent to your email first."})
    pending = _pending_first_change(db, admin)
    if not challenge.password_change_required or pending is None:
        raise HTTPException(status_code=400, detail={"code": "password_change_not_pending", "message": "A password change is not required for this sign-in."})
    valid, message = validate_password_strength(data.new_password)
    if not valid:
        raise HTTPException(status_code=400, detail={"code": "weak_password", "message": message})
    if verify_password(data.new_password, admin.hashed_password):
        raise HTTPException(status_code=400, detail={"code": "same_password", "message": "New password must be different from the current password"})
    policy_error = _password_policy_error(db, admin, data.new_password)
    if policy_error:
        raise HTTPException(status_code=400, detail={"code": "weak_password", "message": policy_error})
    admin.hashed_password = hash_password(data.new_password)
    _record_password(db, admin)
    pending.value_bool = False
    challenge.password_change_required = False
    login_security.consume(db, challenge)
    return _finish_platform_login(db, admin, device_hash, request, trust=data.trust_device if challenge.otp_required else None)


def _create_platform_reset_token(admin: SuperAdmin, expires_minutes: int = PLATFORM_PASSWORD_RESET_EXPIRE_MINUTES) -> str:
    now = datetime.now(timezone.utc)
    return jwt.encode({
        "sub": str(admin.id),
        "email": admin.email.strip().lower(),
        "pwd": password_reset_token_fingerprint(admin.hashed_password),
        "type": "platform_password_reset",
        "iat": now,
        "exp": now + timedelta(minutes=expires_minutes),
    }, settings.SECRET_KEY, algorithm=settings.ALGORITHM)


def _send_platform_reset_email(admin: SuperAdmin, token: str) -> None:
    if not (settings.SMTP_HOST and settings.SMTP_USER and settings.SMTP_PASSWORD):
        logger.warning("Platform password reset email not sent: global SMTP is not configured")
        return

    # The public CRM host serves the SPA fallback for /forgot-password, while
    # /platform/* is redirected to a separate host that currently returns 404.
    reset_url = f"{settings.FRONTEND_BASE_URL.rstrip('/')}/forgot-password?platform_reset_token={token}"
    message = EmailMessage()
    message["Subject"] = "Reset your DigitCRM Platform password"
    message["From"] = settings.EMAILS_FROM or settings.SMTP_USER
    message["To"] = admin.email
    message.set_content(
        f"Hello {admin.full_name},\n\nUse this link to reset your Platform password: {reset_url}\n\n"
        f"This link expires in {PLATFORM_PASSWORD_RESET_EXPIRE_MINUTES} minutes. If you did not request it, you can ignore this email."
    )
    with smtplib.SMTP(settings.SMTP_HOST, int(settings.SMTP_PORT), timeout=30) as server:
        server.starttls(context=ssl.create_default_context())
        server.login(settings.SMTP_USER, settings.SMTP_PASSWORD)
        server.send_message(message)


PLATFORM_FORGOT_PASSWORD_KEY = "platform_forgot_password_enabled"


def platform_forgot_password_enabled(db: Session) -> bool:
    setting = db.query(PlatformSetting).filter(PlatformSetting.key == PLATFORM_FORGOT_PASSWORD_KEY).first()
    return bool(setting.value_bool) if setting else True


@router.get("/login-options")
def platform_login_options(db: Session = Depends(get_master_db_dep)):
    policy = login_security.get_policy(db)
    db.commit()
    return {
        "forgot_password_enabled": platform_forgot_password_enabled(db),
        "force_first_login": _platform_setting(db, "platform_force_first_login"),
        "new_device_alert": _platform_setting(db, "platform_new_device_alert"),
        "otp_mode": policy.otp_mode,
        "captcha_mode": policy.captcha_mode,
    }


@protected_router.put("/settings/login-security")
def update_platform_login_security(data: PlatformLoginSecurityUpdate, request: Request, db: Session = Depends(get_master_db_dep)):
    policy = login_security.get_policy(db)
    old = {"otp_mode": policy.otp_mode, "captcha_mode": policy.captcha_mode}
    if data.otp_mode is not None:
        if data.otp_mode not in login_security.OTP_MODES:
            raise HTTPException(status_code=400, detail=f"otp_mode must be one of: {', '.join(login_security.OTP_MODES)}")
        if data.otp_mode != "never" and not login_security.smtp_configured():
            raise HTTPException(status_code=400, detail="Configure platform SMTP before enabling OTP, otherwise administrators cannot receive codes.")
        policy.otp_mode = data.otp_mode
    if data.captcha_mode is not None:
        if data.captcha_mode not in login_security.CAPTCHA_MODES:
            raise HTTPException(status_code=400, detail=f"captcha_mode must be one of: {', '.join(login_security.CAPTCHA_MODES)}")
        policy.captcha_mode = data.captcha_mode
    policy.updated_at = datetime.utcnow()
    new = {"otp_mode": policy.otp_mode, "captcha_mode": policy.captcha_mode}
    _write_platform_audit(db, _get_platform_admin(request), "update_platform_login_security", "platform_setting", None, "platform_login_security", "Updated platform OTP / CAPTCHA policy", get_request_ip(request), old_data=old, new_data=new)
    db.commit()
    return new


@protected_router.put("/settings/forgot-password")
def update_platform_forgot_password(data: GlobalMaintenanceUpdate, request: Request, db: Session = Depends(get_master_db_dep)):
    setting = db.query(PlatformSetting).filter(PlatformSetting.key == PLATFORM_FORGOT_PASSWORD_KEY).first()
    old_value = bool(setting.value_bool) if setting else True
    if setting is None:
        setting = PlatformSetting(key=PLATFORM_FORGOT_PASSWORD_KEY, value_bool=data.enabled)
        db.add(setting)
    else:
        setting.value_bool = data.enabled
    _write_platform_audit(db, _get_platform_admin(request), "update_platform_forgot_password", "platform_setting", None, PLATFORM_FORGOT_PASSWORD_KEY, "Updated platform password recovery", get_request_ip(request), old_data={"enabled": old_value}, new_data={"enabled": data.enabled})
    db.commit()
    return {"forgot_password_enabled": data.enabled}



@protected_router.put("/settings/login-control/{control}")
def update_platform_login_control(control: str, data: GlobalMaintenanceUpdate, request: Request, db: Session = Depends(get_master_db_dep)):
    keys = {"force_first_login": "platform_force_first_login", "new_device_alert": "platform_new_device_alert"}
    if control not in keys:
        raise HTTPException(status_code=404, detail="Unknown login control")
    key = keys[control]
    row = db.query(PlatformSetting).filter(PlatformSetting.key == key).first()
    old = bool(row.value_bool) if row else False
    if row is None:
        db.add(PlatformSetting(key=key, value_bool=data.enabled))
    else:
        row.value_bool = data.enabled
    _write_platform_audit(db, _get_platform_admin(request), "update_platform_login_control", "platform_setting", None, key, "Updated platform login control", get_request_ip(request), old_data={"enabled": old}, new_data={"enabled": data.enabled})
    db.commit()
    return {"enabled": data.enabled}


@router.post("/forgot-password")
def platform_forgot_password(data: PlatformForgotPasswordRequest, db: Session = Depends(get_master_db_dep)):
    """Request a reset link without revealing whether a Platform account exists."""
    if not platform_forgot_password_enabled(db):
        raise HTTPException(status_code=403, detail="Platform password recovery is disabled")
    identifier = data.email.strip()
    by = SuperAdmin.email == identifier.lower() if "@" in identifier else SuperAdmin.username == identifier
    admin = db.query(SuperAdmin).filter(by, SuperAdmin.is_active == True).first()
    if admin:
        try:
            _send_platform_reset_email(admin, _create_platform_reset_token(admin))
        except Exception:
            logger.exception("Unable to send Platform password reset email")
    return {"message": "If an active Platform account matches, a password reset link has been sent to its registered e-mail."}


# ─── Sign-in page: live status and contact administrator (no sign-in) ─────────

CONTACT_CATEGORIES = ("I’m locked out", "I lost my authenticator device", "I need platform access", "Report suspicious activity")
CONTACT_LIMIT_PER_HOUR = 5
_login_status_cache: dict = {}


@router.get("/login/status")
def platform_login_status(db: Session = Depends(get_master_db_dep)):
    """Only what the sign-in page shows to anyone: whether the platform is operational, how many regions it runs in
    and the API's p95 latency over 24 h (cached 60 s). No tenant, billing or release figures."""
    hit = _login_status_cache.get("v")
    if hit and _clock() - hit[0] < 60:
        return hit[1]
    try:
        db.execute(text("SELECT 1"))
        operational = True
    except Exception:
        logger.exception("Platform login status: database check failed")
        operational = False
    regions = p95 = None
    try:
        from app.services import platform_infrastructure, platform_rate_limits
        regions = len({e.get("region") or platform_infrastructure.DEFAULT_REGION for e in platform_infrastructure.server_inventory()})
        p95 = platform_rate_limits.p95_ms(db) if operational else None
    except Exception:  # noqa: BLE001 - the page shows "—" for anything unavailable
        logger.exception("Platform login status: metrics unavailable")
    body = {"operational": operational, "regions": regions, "p95_ms": p95}
    _login_status_cache["v"] = (_clock(), body)
    return body


def _send_contact_admin_email(recipients: list[str], ref: str, data: PlatformContactAdminRequest, ip: str, user_agent: str) -> None:
    message = EmailMessage()
    message["Subject"] = f"[{ref}] Platform console: {data.category}"
    message["From"] = settings.EMAILS_FROM or settings.SMTP_USER
    message["To"] = ", ".join(recipients)
    message.set_content(f"A request was sent from the platform sign-in page.\n\nReference: {ref}\nFrom: {data.contact}\nRequest: {data.category}\n"
                        f"Details: {data.message.strip() or '—'}\n\nIP address: {ip}\nBrowser: {user_agent}\n\n"
                        "Verify the requester's identity through a known channel before acting on it.")
    with smtplib.SMTP(settings.SMTP_HOST, int(settings.SMTP_PORT), timeout=30) as server:
        server.starttls(context=ssl.create_default_context())
        server.login(settings.SMTP_USER, settings.SMTP_PASSWORD)
        server.send_message(message)


@router.post("/login/contact-administrator", status_code=201)
def platform_contact_administrator(data: PlatformContactAdminRequest, request: Request, db: Session = Depends(get_master_db_dep)):
    """Record a request from the sign-in page in the audit trail (reference SEC-<id>) and e-mail the active platform
    administrators. Limited per IP; never reveals whether an account exists."""
    ip = get_request_ip(request)
    if data.category not in CONTACT_CATEGORIES:
        raise HTTPException(status_code=422, detail="Choose what you need")
    contact = " ".join(data.contact.split())
    if not contact:
        raise HTTPException(status_code=422, detail="Tell us who you are so we can reply")
    recent = db.query(PlatformAuditLog.id).filter(PlatformAuditLog.action == "platform_contact_administrator", PlatformAuditLog.ip_address == ip,
                                                  PlatformAuditLog.created_at >= datetime.utcnow() - timedelta(hours=1)).count()
    if recent >= CONTACT_LIMIT_PER_HOUR:
        raise HTTPException(status_code=429, detail="Too many requests from this network – try again later", headers={"Retry-After": "3600"})
    details = {"contact": contact, "category": data.category, "message": data.message.strip()[:2000] or None}
    row = PlatformAuditLog(super_admin_id=None, action="platform_contact_administrator", entity_type="platform_setting", entity_id=None,
                           entity_name="Platform sign-in", description=f"Sign-in page request from '{contact[:100]}': {data.category}", ip_address=ip,
                           new_data=details, created_at=datetime.utcnow())
    db.add(row)
    db.flush()
    ref = f"SEC-{row.id:04d}"
    row.new_data = {**details, "reference": ref}
    db.commit()
    data.contact = contact
    recipients = [e for (e,) in db.query(SuperAdmin.email).filter(SuperAdmin.is_active == True).all() if e]   # noqa: E712
    delivered = False
    if recipients and settings.SMTP_HOST and settings.SMTP_USER and settings.SMTP_PASSWORD:
        try:
            _send_contact_admin_email(recipients, ref, data, ip, request.headers.get("user-agent", "Unknown"))
            delivered = True
        except Exception:
            logger.exception("Contact-administrator e-mail %s not sent", ref)
    return {"reference": ref, "notified": delivered,
            "message": f"Ticket {ref} has been sent to the platform security team." if delivered
            else f"Ticket {ref} has been logged for the platform security team."}


@router.post("/reset-password")
def platform_reset_password(data: PlatformResetPasswordRequest, db: Session = Depends(get_master_db_dep)):
    if data.new_password != data.confirm_password:
        raise HTTPException(status_code=400, detail="Passwords must match")
    valid, message = validate_password_strength(data.new_password)
    if not valid:
        raise HTTPException(status_code=400, detail=message)

    payload = verify_token(data.token, "platform_password_reset")
    if not payload:
        raise HTTPException(status_code=400, detail="This password reset link is invalid or has expired")
    admin = db.query(SuperAdmin).filter(
        SuperAdmin.id == int(payload.get("sub", 0)),
        SuperAdmin.is_active == True,
    ).first()
    if not admin or payload.get("pwd") != password_reset_token_fingerprint(admin.hashed_password):
        raise HTTPException(status_code=400, detail="This password reset link is invalid or has expired")
    policy_error = _password_policy_error(db, admin, data.new_password)
    if policy_error:
        raise HTTPException(status_code=400, detail=policy_error)

    admin.hashed_password = hash_password(data.new_password)
    _record_password(db, admin)
    pending = db.query(PlatformSetting).filter(PlatformSetting.key == f"platform_first_change_{admin.id}").first()
    if pending:
        pending.value_bool = False
    db.commit()
    return {"message": "Platform password has been reset successfully"}


