@router.get("/config")
def get_platform_config():
    env = "PRODUCTION"
    if settings.DEBUG:
        env = "DEVELOPMENT"
    elif "staging" in (settings.FRONTEND_BASE_URL or "").lower():
        env = "STAGING"
    return {
        "environment": env,
        "app_name": settings.APP_NAME,
        "app_version": settings.APP_VERSION,
        "debug": settings.DEBUG,
    }


@protected_router.get("/me")
def platform_me(admin: SuperAdmin = Depends(require_platform_super_admin)):
    return {"full_name": admin.full_name, "username": admin.username, "email": admin.email}

@protected_router.get("/account-activity")
def platform_account_activity(
    admin: SuperAdmin = Depends(require_platform_super_admin),
    db: Session = Depends(get_master_db_dep),
):
    query = db.query(PlatformAuditLog).filter(PlatformAuditLog.super_admin_id == admin.id)
    logout_query = query.filter(PlatformAuditLog.action == "platform_logout")
    latest = logout_query.order_by(PlatformAuditLog.created_at.desc()).first()
    latest_login = query.filter(PlatformAuditLog.action == "platform_login").order_by(PlatformAuditLog.created_at.desc()).first()
    events = query.order_by(PlatformAuditLog.created_at.desc(), PlatformAuditLog.id.desc()).limit(20).all()
    return {
        "self_logout_count": logout_query.count(),
        "latest_logout": latest.created_at if latest else None,
        "last_login": latest_login.created_at if latest_login else None,
        "activity": [{"id": event.id, "action": event.action, "description": event.description, "entity_name": event.entity_name, "entity_type": event.entity_type, "created_at": event.created_at} for event in events],
    }


@protected_router.post("/logout")
def platform_logout(
    request: Request,
    admin: SuperAdmin = Depends(require_platform_super_admin),
    db: Session = Depends(get_master_db_dep),
):
    request.state.platform_session.is_active = False
    _write_platform_audit(db, admin, "platform_logout", "super_admin", admin.id, admin.username, "Signed out of the platform", get_request_ip(request))
    db.commit()
    return {"message": "Signed out"}

@protected_router.post("/request-password-reset")
def platform_request_password_reset(admin: SuperAdmin = Depends(require_platform_super_admin)):
    try:
        _send_platform_reset_email(admin, _create_platform_reset_token(admin))
    except Exception:
        logger.exception("Unable to send platform password reset email")
        raise HTTPException(status_code=503, detail="Unable to send the reset email. Please check platform email settings and try again.")
    return {"message": "Password reset link sent to your email"}

@protected_router.post("/change-password")
def platform_change_password(
    data: PlatformChangePasswordRequest,
    admin: SuperAdmin = Depends(require_platform_super_admin),
    db: Session = Depends(get_master_db_dep),
):
    if not verify_password(data.current_password, admin.hashed_password):
        raise HTTPException(status_code=400, detail="Current password is incorrect")
    if data.new_password != data.confirm_password:
        raise HTTPException(status_code=400, detail="Passwords must match")
    if verify_password(data.new_password, admin.hashed_password):
        raise HTTPException(status_code=400, detail="New password must be different from the current password")
    valid, message = validate_password_strength(data.new_password)
    if not valid:
        raise HTTPException(status_code=400, detail=message)
    account = db.query(SuperAdmin).filter(SuperAdmin.id == admin.id, SuperAdmin.is_active == True).first()
    if not account:
        raise HTTPException(status_code=400, detail="Platform administrator is no longer active")
    policy_error = _password_policy_error(db, account, data.new_password)
    if policy_error:
        raise HTTPException(status_code=400, detail=policy_error)
    account.hashed_password = hash_password(data.new_password)
    _record_password(db, account)
    db.commit()
    return {"message": "Password changed successfully"}

class PlatformSessionTimeoutUpdate(BaseModel):
    timeout_minutes: int


@protected_router.get("/settings/session-timeout")
def get_platform_session_timeout(db: Session = Depends(get_master_db_dep)):
    policy = db.query(PlatformSessionPolicy).filter(PlatformSessionPolicy.id == 1).first()
    return {"timeout_minutes": policy.timeout_minutes if policy else 30}


@protected_router.put("/settings/session-timeout")
def update_platform_session_timeout(data: PlatformSessionTimeoutUpdate, request: Request, db: Session = Depends(get_master_db_dep)):
    if not 1 <= data.timeout_minutes <= 1440:
        raise HTTPException(status_code=400, detail="Timeout must be between 1 and 1440 minutes")
    policy = db.query(PlatformSessionPolicy).filter(PlatformSessionPolicy.id == 1).first()
    old = policy.timeout_minutes if policy else 30
    if policy is None:
        policy = PlatformSessionPolicy(id=1, timeout_minutes=data.timeout_minutes)
        db.add(policy)
    else:
        policy.timeout_minutes = data.timeout_minutes
    _write_platform_audit(db, _get_platform_admin(request), "update_platform_session_timeout", "platform_setting", None, "session_timeout", "Updated platform session timeout", get_request_ip(request), old_data={"minutes": old}, new_data={"minutes": data.timeout_minutes})
    db.commit()
    return {"timeout_minutes": data.timeout_minutes}


PLATFORM_LOGO_EXTENSIONS = {".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg"}


class PlatformBrandingUpdate(BaseModel):
    product_name: str
    support_email: Optional[EmailStr] = None
    allow_tenant_branding: bool

    @field_validator("product_name")
    @classmethod
    def _clean_product_name(cls, value: str) -> str:
        value = value.strip()
        if not value:
            raise ValueError("Product name is required")
        if len(value) > 150:
            raise ValueError("Product name must be 150 characters or fewer")
        return value


def _branding_dict(row: Optional[PlatformBranding]) -> dict:
    if row is None:
        return {"product_name": "", "support_email": "", "logo_url": "", "allow_tenant_branding": True}
    version = int(row.updated_at.timestamp()) if row.updated_at else 0
    logo_url = f"{row.logo_path}?v={version}" if row.logo_path else ""
    return {
        "product_name": row.product_name or "",
        "support_email": row.support_email or "",
        "logo_url": logo_url,
        "allow_tenant_branding": bool(row.allow_tenant_branding),
    }


def _get_or_create_branding(db: Session) -> PlatformBranding:
    row = db.query(PlatformBranding).filter(PlatformBranding.id == 1).first()
    if row is None:
        row = PlatformBranding(id=1, product_name="", support_email="", logo_path="", allow_tenant_branding=True)
        db.add(row)
    return row


@protected_router.get("/settings/branding")
def get_platform_branding(db: Session = Depends(get_master_db_dep)):
    return _branding_dict(db.query(PlatformBranding).filter(PlatformBranding.id == 1).first())


@protected_router.put("/settings/branding")
def update_platform_branding(data: PlatformBrandingUpdate, request: Request, db: Session = Depends(get_master_db_dep)):
    row = _get_or_create_branding(db)
    old = _branding_dict(row)
    row.product_name = data.product_name
    row.support_email = str(data.support_email or "")
    row.allow_tenant_branding = data.allow_tenant_branding
    _write_platform_audit(db, _get_platform_admin(request), "update_platform_branding", "platform_setting", None, "branding", "Updated platform white-label branding", get_request_ip(request), old_data=old, new_data=data.model_dump(mode="json"))
    db.commit()
    db.refresh(row)
    return _branding_dict(row)


@protected_router.post("/settings/branding/logo")
async def upload_platform_logo(request: Request, file: UploadFile = File(...), db: Session = Depends(get_master_db_dep)):
    suffix = Path(file.filename or "").suffix.lower()
    if suffix not in PLATFORM_LOGO_EXTENSIONS:
        raise HTTPException(status_code=400, detail="Logo must be a PNG, JPG, GIF, WEBP or SVG image")
    contents = await file.read()
    if not contents:
        raise HTTPException(status_code=400, detail="Uploaded logo is empty")
    if len(contents) > 2 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="Logo must be 2 MB or smaller")
    upload_dir = Path(settings.UPLOAD_DIR).resolve() / "platform"
    upload_dir.mkdir(parents=True, exist_ok=True)
    for old_file in upload_dir.glob("product_logo.*"):
        old_file.unlink()
    (upload_dir / f"product_logo{suffix}").write_bytes(contents)
    row = _get_or_create_branding(db)
    row.logo_path = f"/uploads/platform/product_logo{suffix}"
    row.updated_at = datetime.utcnow()
    _write_platform_audit(db, _get_platform_admin(request), "upload_platform_logo", "platform_setting", None, "branding", "Uploaded platform product logo", get_request_ip(request))
    db.commit()
    db.refresh(row)
    return _branding_dict(row)


@protected_router.delete("/settings/branding/logo")
def delete_platform_logo(request: Request, db: Session = Depends(get_master_db_dep)):
    row = db.query(PlatformBranding).filter(PlatformBranding.id == 1).first()
    if row and row.logo_path:
        for old_file in (Path(settings.UPLOAD_DIR).resolve() / "platform").glob("product_logo.*"):
            old_file.unlink()
        row.logo_path = ""
        _write_platform_audit(db, _get_platform_admin(request), "delete_platform_logo", "platform_setting", None, "branding", "Removed platform product logo", get_request_ip(request))
        db.commit()
        db.refresh(row)
    return _branding_dict(row)


PLATFORM_DATA_REGIONS = {"ap-south-1", "ap-south-2", "ap-southeast-1", "eu-central-1", "us-east-1"}


class PlatformDataComplianceUpdate(BaseModel):
    default_region: str
    retention_years: int
    encrypt_documents_at_rest: bool


def _data_compliance_dict(row: Optional[PlatformDataCompliance]) -> dict:
    if row is None:
        return {"default_region": "ap-south-1", "retention_years": 7, "encrypt_documents_at_rest": True}
    return {
        "default_region": row.default_region,
        "retention_years": row.retention_years,
        "encrypt_documents_at_rest": bool(row.encrypt_documents_at_rest),
    }


@protected_router.get("/settings/data-compliance")
def get_platform_data_compliance(db: Session = Depends(get_master_db_dep)):
    return _data_compliance_dict(db.query(PlatformDataCompliance).filter(PlatformDataCompliance.id == 1).first())


@protected_router.put("/settings/data-compliance")
def update_platform_data_compliance(data: PlatformDataComplianceUpdate, request: Request, db: Session = Depends(get_master_db_dep)):
    if data.default_region not in PLATFORM_DATA_REGIONS:
        raise HTTPException(status_code=400, detail="Unsupported default region")
    if not 1 <= data.retention_years <= 25:
        raise HTTPException(status_code=400, detail="Retention must be between 1 and 25 years")
    row = db.query(PlatformDataCompliance).filter(PlatformDataCompliance.id == 1).first()
    old = _data_compliance_dict(row)
    if row is None:
        row = PlatformDataCompliance(id=1)
        db.add(row)
    row.default_region = data.default_region
    row.retention_years = data.retention_years
    row.encrypt_documents_at_rest = data.encrypt_documents_at_rest
    _write_platform_audit(db, _get_platform_admin(request), "update_platform_data_compliance", "platform_setting", None, "data_compliance", "Updated platform data & compliance settings", get_request_ip(request), old_data=old, new_data=data.model_dump())
    db.commit()
    return _data_compliance_dict(row)


