@protected_router.post("/session/activity")
def platform_session_activity(request: Request, db: Session = Depends(get_master_db_dep)):
    session = db.query(PlatformSession).filter(PlatformSession.id == request.state.platform_session.id).first()
    session.last_active = datetime.utcnow()
    db.commit()
    policy = db.query(PlatformSessionPolicy).filter(PlatformSessionPolicy.id == 1).first()
    return {"timeout_minutes": policy.timeout_minutes if policy else 30}


@protected_router.get("/settings/maintenance")
def get_global_maintenance(db: Session = Depends(get_master_db_dep)):
    return {"enabled": get_global_maintenance_mode(db)}


@protected_router.put("/settings/maintenance")
def update_global_maintenance(
    data: GlobalMaintenanceUpdate,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    admin = _get_platform_admin(request)
    setting = db.query(PlatformSetting).filter(PlatformSetting.key == GLOBAL_MAINTENANCE_KEY).first()
    old_value = bool(setting.value_bool) if setting else False
    if data.enabled and not old_value:
        gate = _four_eyes_gate(db, request, "update_global_maintenance", "platform_setting", None, GLOBAL_MAINTENANCE_KEY,
                               "Turn on global maintenance mode for every tenant", {"enabled": True})
        if gate:
            return gate
    if setting is None:
        setting = PlatformSetting(key=GLOBAL_MAINTENANCE_KEY, value_bool=data.enabled)
        db.add(setting)
    else:
        setting.value_bool = data.enabled
    _write_platform_audit(
        db=db, admin=admin, action="update_global_maintenance", entity_type="platform_setting",
        entity_id=None, entity_name=GLOBAL_MAINTENANCE_KEY,
        description=f"Global maintenance mode {'enabled' if data.enabled else 'disabled'}",
        ip=get_request_ip(request), old_data={"enabled": old_value}, new_data={"enabled": data.enabled},
    )
    db.commit()
    return {"enabled": data.enabled}


