def _tenant_storage_totals(tenant_slug: str) -> tuple[int, int, float]:
    return tenant_file_storage_totals(tenant_slug)


def _refresh_tenant_storage_usage(db: Session, tenant: Tenant) -> tuple[int, int, float]:
    return refresh_tenant_storage_usage(db, tenant)

@protected_router.get("/subscriptions/summary")
def subscription_summary(db: Session = Depends(get_master_db_dep)):
    """Return the authoritative billing classification for every tenant."""
    current_time = now_ist()
    renewal_window_end = current_time + timedelta(days=30)
    counts = {"active": 0, "trial": 0, "expired": 0, "renewing": 0}
    subscriptions = []
    for tenant in db.query(Tenant).order_by(Tenant.created_at.desc()).all():
        renewal_date = tenant.subscription_end_date or (tenant.trial_ends_at if tenant.billing_status == "trial" else None)
        if tenant.billing_status in {"cancelled", "past_due"} or (renewal_date and renewal_date < current_time): subscription_state = "expired"
        elif tenant.billing_status == "trial" or tenant.status == "trial": subscription_state = "trial"
        elif renewal_date and renewal_date <= renewal_window_end: subscription_state = "renewing"
        else: subscription_state = "active"
        counts[subscription_state] += 1
        row = TenantResponse.model_validate(tenant).model_dump(mode="json")
        row.update({"subscription_state": subscription_state, "renewal_date": renewal_date})
        subscriptions.append(row)
    return {"generated_at": current_time, "total_subscriptions": len(subscriptions), "active": counts["active"], "trials": counts["trial"], "expired": counts["expired"], "renewals_due": counts["renewing"], "tenants": subscriptions}

@protected_router.get("/dashboard/tenant-usage")
def dashboard_tenant_usage(db: Session = Depends(get_master_db_dep)):
    """Fast, platform-wide storage/status feed for the dashboard.

    This deliberately reads the master tenant records only. It does not open each
    tenant database or scan file storage, keeping dashboard refreshes reliable.
    """
    tenants = db.query(Tenant).order_by(Tenant.created_at.desc()).all()
    return [
        {
            "id": tenant.id,
            "name": tenant.name,
            "status": tenant.status,
            "used_storage": float(tenant.used_storage or 0),
            "storage_limit_mb": int(tenant.storage_limit_mb or 0),
        }
        for tenant in tenants
    ]

@protected_router.get("/dashboard/infrastructure")
def dashboard_infrastructure(request: Request, db: Session = Depends(get_master_db_dep)):
    """Live server metrics, database health and tenant-to-server mapping."""
    query = db.query(Tenant)
    allowed = scoped_tenant_ids(request)
    if allowed is not None:
        query = query.filter(Tenant.id.in_(allowed or [0]))
    return infrastructure.infrastructure_snapshot(query.order_by(Tenant.name).all())


