@protected_router.get("/tenants/{tenant_id}/features")
def get_tenant_features(tenant_id: int, db: Session = Depends(get_master_db_dep)):
    tenant = db.query(Tenant).filter(Tenant.id == tenant_id).first()
    if not tenant:
        raise HTTPException(status_code=404, detail="Tenant not found")

    all_features = db.query(Feature).order_by(
        Feature.module.asc(),
        Feature.name.asc(),
    ).all()

    enabled_ids = {
        row.feature_id
        for row in db.query(TenantFeature).filter(
            TenantFeature.tenant_id == tenant_id,
            TenantFeature.enabled == True,
        ).all()
    }

    if not enabled_ids and tenant.plan_id:
        enabled_ids = {
            row.feature_id
            for row in db.query(PlanFeature).filter(
                PlanFeature.plan_id == tenant.plan_id,
                PlanFeature.enabled == True,
            ).all()
        }

    return {
        "tenant_id": tenant_id,
        "feature_ids": list(enabled_ids),
        "features": [
            {
                "id": feature.id,
                "key": feature.key,
                "name": feature.name,
                "module": feature.module,
                "description": feature.description,
                "enabled": feature.id in enabled_ids,
            }
            for feature in all_features
        ],
    }

@protected_router.put("/tenants/{tenant_id}/features")
def update_tenant_features(
    tenant_id: int,
    data: PlanFeatureUpdate,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    tenant = db.query(Tenant).filter(Tenant.id == tenant_id).first()
    if not tenant:
        raise HTTPException(status_code=404, detail="Tenant not found")

    admin = _get_platform_admin(request)
    ip = get_request_ip(request)

    feature_ids = sorted(set(data.feature_ids or []))

    if feature_ids:
        existing_count = db.query(Feature).filter(Feature.id.in_(feature_ids)).count()
        if existing_count != len(feature_ids):
            raise HTTPException(status_code=400, detail="One or more feature IDs are invalid")

    old_ids = [
        row.feature_id
        for row in db.query(TenantFeature).filter(
            TenantFeature.tenant_id == tenant_id,
            TenantFeature.enabled == True,
        ).all()
    ]

    features = db.query(Feature).filter(Feature.id.in_(feature_ids)).all() if feature_ids else []
    enabled_feature_keys = [feature.key for feature in features]

    try:
      tenant_db = get_tenant_session(tenant.slug)
      tenant_db.info["tenant_slug"] = tenant.slug
      try:
          sync_tenant_runtime_catalog(
              tenant_db,
              enabled_feature_keys=enabled_feature_keys,
              assign_permissions_to_admin_role=True,
          )
          tenant_db.commit()
      except Exception:
          tenant_db.rollback()
          raise
      finally:
          tenant_db.close()
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Tenant DB sync failed: {str(exc)}")

    db.query(TenantFeature).filter(TenantFeature.tenant_id == tenant_id).delete()

    for feature_id in feature_ids:
        db.add(TenantFeature(
            tenant_id=tenant_id,
            feature_id=feature_id,
            enabled=True,
            source="custom_override",
        ))

    _write_platform_audit(
        db=db,
        admin=admin,
        action="update_tenant_features",
        entity_type="tenant",
        entity_id=tenant_id,
        entity_name=tenant.name,
        description=f"Updated feature overrides for tenant '{tenant.slug}' ({len(feature_ids)} features)",
        ip=ip,
        old_data={"feature_ids": old_ids},
        new_data={"feature_ids": feature_ids, "feature_keys": enabled_feature_keys},
    )

    db.commit()

    return {
        "tenant_id": tenant_id,
        "feature_ids": feature_ids,
    }

@protected_router.post("/tenants/{tenant_id}/backup")
def create_tenant_backup(
    tenant_id: int,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    tenant = db.query(Tenant).filter(Tenant.id == tenant_id).first()
    if not tenant:
        raise HTTPException(status_code=404, detail="Tenant not found")

    from app.models.platform_backup import TenantBackup
    from app.services.platform_backup_service import run_backup
    backup = TenantBackup(tenant_id=tenant.id, name="Tenant backup", status="pending")
    db.add(backup)
    db.commit()
    db.refresh(backup)
