@protected_router.get("/tenants/{tenant_id}/feature-usage")
def get_tenant_feature_usage(
    tenant_id: int,
    days: int = 30,
    db: Session = Depends(get_master_db_dep),
):
    tenant = db.query(Tenant).filter(Tenant.id == tenant_id).first()
    if not tenant:
        raise HTTPException(status_code=404, detail="Tenant not found")

    since = now_ist() - timedelta(days=max(1, days))

    try:
        tenant_db = get_tenant_session(tenant.slug)
        try:
            rows = tenant_db.execute(
                text("""
                    SELECT module, action, COUNT(*) AS usage_count, MAX(created_at) AS last_used_at
                    FROM audit_logs
                    WHERE created_at >= :since
                    GROUP BY module, action
                    ORDER BY usage_count DESC
                """),
                {"since": since},
            ).fetchall()

            return [
                {
                    "module": row.module,
                    "action": row.action,
                    "usage_count": int(row.usage_count or 0),
                    "last_used_at": row.last_used_at.isoformat() if row.last_used_at else None,
                }
                for row in rows
            ]
        finally:
            tenant_db.close()
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to load feature usage: {str(exc)}")

@protected_router.post("/tenant-users/preview")
async def preview_tenant_users(file: UploadFile = File(...)):
    import csv
    import io
    import os

    raw = await file.read(2 * 1024 * 1024 + 1)
    if len(raw) > 2 * 1024 * 1024:
        raise HTTPException(400, "File exceeds the 2 MB limit")
    extension = os.path.splitext(file.filename or "")[1].lower()
    try:
        if extension == ".csv":
            rows = list(csv.reader(io.StringIO(raw.decode("utf-8-sig"))))
        elif extension == ".xlsx":
            from openpyxl import load_workbook
            workbook = load_workbook(io.BytesIO(raw), read_only=True, data_only=True)
            rows = list(workbook.active.iter_rows(values_only=True))
            workbook.close()
        elif extension == ".xls":
            import xlrd
            sheet = xlrd.open_workbook(file_contents=raw).sheet_by_index(0)
            rows = [sheet.row_values(i) for i in range(sheet.nrows)]
        else:
            raise HTTPException(400, "Choose an .xlsx, .xls or .csv file")
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(400, "Unable to read the file. Check its format and try again.")
    if not rows or len(rows) > 1001:
        raise HTTPException(400, "Provide a header row and at most 1,000 users")
    headers = [str(value or "").strip().lower().replace(" ", "_") for value in rows[0]]
    required = ("full_name", "email", "username", "password", "role")
    if any(name not in headers for name in required) or len(headers) != len(set(headers)):
        raise HTTPException(400, "Required columns: Full Name, Email, Username, Password, Role")
    users = []
    errors = []
    seen_names, seen_emails = set(), set()
    for row_number, row in enumerate(rows[1:], 2):
        if not any(str(value or "").strip() for value in row):
            continue
        values = {key: str(row[headers.index(key)] or "").strip() if headers.index(key) < len(row) else "" for key in required}
        values["username"] = values["username"].lower()
        values["role"] = values["role"].lower()
        issues = []
        try:
            parsed = TenantAdditionalUser(**values)
            valid, reason = validate_password_strength(parsed.password)
            if not valid: issues.append(reason)
            if not parsed.full_name.strip() or len(parsed.full_name) > 100: issues.append("Full name is required (maximum 100 characters)")
            if not parsed.role.strip() or len(parsed.role) > 50: issues.append("Role is required (maximum 50 characters)")
            if parsed.username in seen_names or parsed.username == "admin": issues.append("Duplicate or reserved username")
            if str(parsed.email).lower() in seen_emails: issues.append("Duplicate email")
            seen_names.add(parsed.username)
            seen_emails.add(str(parsed.email).lower())
        except Exception:
            issues.append("Invalid user details or email")
        if issues: errors.append({"row": row_number, "message": "; ".join(issues)})
        users.append(values)
    if not users: raise HTTPException(400, "The file contains no users")
    return {"users": users, "errors": errors}

@protected_router.post("/tenants", response_model=TenantResponse, status_code=201)
def create_tenant(
    data: TenantCreate,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    admin = _get_platform_admin(request)
    ip = get_request_ip(request)

    try:
        if db.query(Tenant).filter(Tenant.slug == data.slug).first():
            raise HTTPException(status_code=400, detail="Slug already exists")
        if db.query(Tenant).filter(Tenant.subdomain == data.subdomain).first():
            raise HTTPException(status_code=400, detail="Subdomain already exists")

        plan_id = data.plan_id if data.plan_id and data.plan_id != 0 else None
        if plan_id is not None:
            plan = db.query(Plan).filter(Plan.id == plan_id).first()
            if not plan:
                raise HTTPException(status_code=400, detail=f"Invalid plan_id: {plan_id}")

        additional_users = data.additional_users or []
        if data.max_users >= 0 and len(additional_users) + 1 > data.max_users:
            raise HTTPException(status_code=400, detail=f"The selected plan allows {data.max_users} users, including the administrator.")

        usernames = {"admin"}
        emails = {str(data.admin_email).strip().lower()}
        for user in additional_users:
            if user.username in usernames:
                raise HTTPException(status_code=400, detail=f"Duplicate username: {user.username}")
            if str(user.email).strip().lower() in emails:
                raise HTTPException(status_code=400, detail=f"Duplicate email: {user.email}")
            if not user.role.strip() or len(user.role.strip()) > 50:
                raise HTTPException(status_code=400, detail="Role must contain 1 to 50 characters")
            valid_password, password_message = validate_password_strength(user.password)
            if not valid_password:
                raise HTTPException(status_code=400, detail=f"Invalid password for {user.email}: {password_message}")
            usernames.add(user.username)
            emails.add(str(user.email).strip().lower())

        # Resolve enabled module keys for provisioning
        enabled_module_keys = data.module_overrides
        if enabled_module_keys is None and plan_id is not None:
            rows = db.query(PlanFeature, Feature).join(
                Feature, PlanFeature.feature_id == Feature.id
            ).filter(PlanFeature.plan_id == plan_id, PlanFeature.enabled == True).all()
            enabled_module_keys = [row.Feature.key for row in rows]

        db_name = build_tenant_db_name(data.slug)
        tenant = Tenant(
            name=data.name,
            slug=data.slug,
            subdomain=data.subdomain,
            admin_email=data.admin_email,
            admin_name=data.admin_name,
            db_name=db_name,
            plan_id=plan_id,
            max_users=data.max_users,
            normal_login_expiry_minutes=max(1, data.normal_login_expiry_minutes),
            remember_me_expiry_minutes=max(
                max(1, data.normal_login_expiry_minutes),
                data.remember_me_expiry_minutes,
            ),
            inactivity_timeout_minutes=data.inactivity_timeout_minutes,
            session_warning_minutes=data.session_warning_minutes,
            smtp_host=data.smtp_host,
            smtp_port=data.smtp_port if data.smtp_port and data.smtp_port > 0 else None,
            smtp_user=data.smtp_user,
            smtp_password=data.smtp_password,
            smtp_use_tls=data.smtp_use_tls,
            smtp_use_ssl=data.smtp_use_ssl,
            from_email=data.from_email,
            company_mail=data.company_mail,
            address=data.address,
            street_address=data.street_address,
            pincode=data.pincode,
            country=(data.country or "India").strip() or "India",
            state=data.state,
            city_district=data.city_district,
            area_locality=data.area_locality,
            forgot_password_enabled=data.forgot_password_enabled,
            self_service_reset_limit_count=max(0, data.self_service_reset_limit_count),
            self_service_reset_limit_days=max(1, data.self_service_reset_limit_days),
            forgot_password_send_max_attempts=max(1, data.forgot_password_send_max_attempts),
            forgot_password_send_window_minutes=max(1, data.forgot_password_send_window_minutes),
            forgot_password_ip_max_attempts=max(1, data.forgot_password_ip_max_attempts),
            forgot_password_ip_window_minutes=max(1, data.forgot_password_ip_window_minutes),
            password_expiry_enabled=data.password_expiry_enabled,
            password_expiry_days=max(1, data.password_expiry_days),
            notes=data.notes,
            status="trial",
            trial_ends_at=now_ist() + timedelta(days=data.trial_days),
            storage_limit_mb=max(1, data.storage_limit_mb),
            billing_email=data.billing_email,
            billing_status=data.billing_status or "trial",
            subscription_end_date=data.subscription_end_date,
            billing_notes=data.billing_notes,
        )

        db.add(tenant)
        db.commit()
        db.refresh(tenant)

        plan = None
        plan_id = data.plan_id if data.plan_id and data.plan_id != 0 else None

        if plan_id is not None:
            plan = db.query(Plan).filter(Plan.id == plan_id).first()
            if not plan:
                raise HTTPException(status_code=400, detail=f"Invalid plan_id: {plan_id}")

        selected_feature_ids = data.selected_feature_ids

        if selected_feature_ids is None and plan_id is not None:
            rows = db.query(PlanFeature).filter(
                PlanFeature.plan_id == plan_id,
                PlanFeature.enabled == True,
            ).all()
            selected_feature_ids = [row.feature_id for row in rows]

        if selected_feature_ids is None:
            selected_feature_ids = []

        if selected_feature_ids:
            existing_count = db.query(Feature).filter(Feature.id.in_(selected_feature_ids)).count()
            if existing_count != len(set(selected_feature_ids)):
                raise HTTPException(status_code=400, detail="One or more selected features are invalid")

        feature_rows = []
        if selected_feature_ids:
            feature_rows = db.query(Feature).filter(Feature.id.in_(selected_feature_ids)).all()

        enabled_module_keys = data.module_overrides
        if enabled_module_keys is None:
            enabled_module_keys = [feature.key for feature in feature_rows]

        snapshot = TenantPlanSnapshot(
            tenant_id=tenant.id,
            plan_id=plan_id,
            plan_name=plan.name if plan else None,
            plan_slug=plan.slug if plan else None,
            price_monthly=data.price_monthly if data.price_monthly is not None else (plan.price_monthly if plan else 0),
            price_yearly=data.price_yearly if data.price_yearly is not None else (plan.price_yearly if plan else 0),
            max_users=data.max_users,
            storage_limit_mb=data.storage_limit_mb,
            trial_days=data.trial_days,
            billing_status=data.billing_status or "trial",
            subscription_end_date=data.subscription_end_date,
            snapshot_json={
                "plan_id": plan_id,
                "plan_name": plan.name if plan else None,
                "price_monthly": data.price_monthly,
                "price_yearly": data.price_yearly,
                "max_users": data.max_users,
                "storage_limit_mb": data.storage_limit_mb,
                "trial_days": data.trial_days,
                "feature_ids": selected_feature_ids,
                "feature_keys": enabled_module_keys,
            },
        )
        db.add(snapshot)

        for feature_id in sorted(set(selected_feature_ids)):
            db.add(TenantFeature(
                tenant_id=tenant.id,
                feature_id=feature_id,
                enabled=True,
                source="custom_override",
            ))

        db.commit()

        try:
            _provision_tenant_db(
                data.slug,
                data.admin_email,
                data.admin_name,
                data.admin_password,
                enabled_module_keys=enabled_module_keys,
                additional_users=[user.model_dump() for user in additional_users],
            )
            logger.info("Tenant DB provisioned: %s", db_name)
        except Exception as exc:
            db.delete(tenant)
            db.commit()
            logger.exception("Tenant DB provisioning failed")
            raise HTTPException(status_code=500, detail=f"Tenant DB provisioning failed: {str(exc)}")

        _write_platform_audit(
            db=db, admin=admin, action="create_tenant", entity_type="tenant",
            entity_id=tenant.id, entity_name=tenant.name,
            description=f"Tenant '{tenant.slug}' provisioned with DB '{db_name}'",
            ip=ip, new_data={"slug": tenant.slug, "plan_id": plan_id},
        )
        db.commit()
        log_audit(None, None, "platform", "create_tenant", ip, f"tenant={data.slug}")
        return tenant

    except HTTPException:
        raise
    except Exception as exc:
        db.rollback()
        logger.exception("Tenant creation failed")
        raise HTTPException(status_code=500, detail=f"Tenant creation failed: {str(exc)}")

@protected_router.get("/plans/{plan_id}/details")
def get_plan_details(plan_id: int, db: Session = Depends(get_master_db_dep)):
    plan = db.query(Plan).filter(Plan.id == plan_id).first()
    if not plan:
        raise HTTPException(status_code=404, detail="Plan not found")

    all_features = db.query(Feature).order_by(Feature.module.asc(), Feature.name.asc()).all()

    enabled_rows = db.query(PlanFeature).filter(
        PlanFeature.plan_id == plan_id,
        PlanFeature.enabled == True,
    ).all()

    enabled_feature_ids = {row.feature_id for row in enabled_rows}

    return {
        "plan": {
            "id": plan.id,
            "name": plan.name,
            "slug": plan.slug,
            "description": plan.description,
            "price_monthly": plan.price_monthly,
            "price_yearly": plan.price_yearly,
            "max_users": plan.max_users,
            "is_active": plan.is_active,
        },
        "features": [
            {
                "id": feature.id,
                "key": feature.key,
                "name": feature.name,
                "module": feature.module,
                "description": feature.description,
                "enabled": feature.id in enabled_feature_ids,
            }
            for feature in all_features
        ],
    }


def _check_user_limit(tenant: Tenant, new_limit: int) -> None:
    """A tenant's maximum users can't go below the users already active in its database (the count its app enforces)."""
    if new_limit < 1:
        raise HTTPException(status_code=422, detail="Maximum users must be at least 1")
    if tenant.max_users is not None and new_limit >= tenant.max_users:
        return  # raising (or keeping) the limit never strands existing users
    try:
        tenant_db = get_tenant_session(tenant.slug)
        try:
            active = int(tenant_db.execute(text("SELECT COUNT(*) FROM users WHERE is_active = 1")).scalar_one())
        finally:
            tenant_db.close()
    except Exception as exc:
        raise HTTPException(status_code=503, detail=f"Can't lower the user limit: {tenant.name}'s database could not be checked ({str(exc)[:120]})")
    if new_limit < active:
        raise HTTPException(status_code=409, detail=f"{tenant.name} has {active} active users – the maximum can't be set below {active}. "
                                                    "Deactivate users in the tenant first, or choose a limit of at least that many.")


@protected_router.put("/tenants/{tenant_id}", response_model=TenantResponse)
def update_tenant(
    tenant_id: int,
    data: TenantUpdate,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    admin = _get_platform_admin(request)
    ip = get_request_ip(request)

    tenant = db.query(Tenant).filter(Tenant.id == tenant_id).first()
    if not tenant:
        raise HTTPException(status_code=404, detail="Tenant not found")

    updates = data.model_dump(exclude_unset=True)
    old_plan_id = tenant.plan_id

    if "self_service_reset_limit_count" in updates:
        updates["self_service_reset_limit_count"] = max(0, int(updates["self_service_reset_limit_count"]))
    if "self_service_reset_limit_days" in updates:
        updates["self_service_reset_limit_days"] = max(1, int(updates["self_service_reset_limit_days"]))
    if "forgot_password_send_max_attempts" in updates:
        updates["forgot_password_send_max_attempts"] = max(1, int(updates["forgot_password_send_max_attempts"]))
    if "forgot_password_send_window_minutes" in updates:
        updates["forgot_password_send_window_minutes"] = max(1, int(updates["forgot_password_send_window_minutes"]))
    if "forgot_password_ip_max_attempts" in updates:
        updates["forgot_password_ip_max_attempts"] = max(1, int(updates["forgot_password_ip_max_attempts"]))
    if "forgot_password_ip_window_minutes" in updates:
        updates["forgot_password_ip_window_minutes"] = max(1, int(updates["forgot_password_ip_window_minutes"]))
    if "password_expiry_days" in updates:
        updates["password_expiry_days"] = max(1, int(updates["password_expiry_days"]))
    if "normal_login_expiry_minutes" in updates:
        updates["normal_login_expiry_minutes"] = max(1, int(updates["normal_login_expiry_minutes"]))
    if "remember_me_expiry_minutes" in updates:
        base_expiry = int(updates.get("normal_login_expiry_minutes", tenant.normal_login_expiry_minutes or DEFAULT_NORMAL_LOGIN_EXPIRY_MINUTES))
        updates["remember_me_expiry_minutes"] = max(max(1, base_expiry), int(updates["remember_me_expiry_minutes"]))
    if "inactivity_timeout_minutes" in updates:
        updates["inactivity_timeout_minutes"] = max(1, int(updates["inactivity_timeout_minutes"]))
    if "session_warning_minutes" in updates:
        inactivity_timeout = int(updates.get("inactivity_timeout_minutes", tenant.inactivity_timeout_minutes or 30))
        updates["session_warning_minutes"] = max(1, min(max(1, inactivity_timeout), int(updates["session_warning_minutes"])))

    if updates.get("max_users") is not None:
        _check_user_limit(tenant, int(updates["max_users"]))

    old_snapshot = {
        "name": tenant.name,
        "status": tenant.status,
        "plan_id": tenant.plan_id,
        "max_users": tenant.max_users,
    }

    for field, val in updates.items():
        setattr(tenant, field, val)

    # Track plan change
    new_plan_id = updates.get("plan_id", old_plan_id)
    if "plan_id" in updates and new_plan_id != old_plan_id:
        # The tenant's modules follow its new plan; features it had set differently from the old plan stay as they are.
        from app.services import platform_entitlements
        try:
            moved = platform_entitlements.tenant_plan_change(db, tenant, old_plan_id, new_plan_id)
        except Exception as exc:
            db.rollback()
            raise HTTPException(status_code=502, detail=f"Plan not changed: the tenant database could not be updated ({str(exc)[:200]})")
        if moved["added"] or moved["removed"]:
            updates = {**updates, "features_added": moved["added"], "features_removed": moved["removed"]}
        db.add(TenantPlanHistory(
            tenant_id=tenant.id,
            old_plan_id=old_plan_id,
            new_plan_id=new_plan_id,
            changed_by_admin_id=admin.id if admin else None,
            note=f"Plan changed via platform console",
        ))

    _write_platform_audit(
        db=db, admin=admin, action="update_tenant", entity_type="tenant",
        entity_id=tenant.id, entity_name=tenant.name,
        description=f"Tenant '{tenant.slug}' updated",
        ip=ip, old_data=old_snapshot, new_data=updates,
    )
    db.commit()
    db.refresh(tenant)
    return tenant


