@protected_router.get("/features")
def list_features(db: Session = Depends(get_master_db_dep)):
    return db.query(Feature).order_by(Feature.module.asc(), Feature.name.asc()).all()


@protected_router.post("/features", status_code=201)
def create_feature(data: FeatureCreate, db: Session = Depends(get_master_db_dep)):
    key = data.key.strip().lower()
    if db.query(Feature).filter(Feature.key == key).first():
        raise HTTPException(status_code=400, detail="Feature key already exists")
    feature = Feature(
        key=key,
        name=data.name.strip(),
        module=(data.module or "General").strip(),
        description=data.description,
    )
    db.add(feature)
    db.commit()
    db.refresh(feature)
    return feature


class ServiceCreate(FeatureCreate):
    parent_id: Optional[int] = None


def _build_service_catalog(db: Session) -> list[dict]:
    """Module Management catalog. Every item (linked or not) carries its own status."""
    features = db.query(Feature).all()
    by_key = {feature.key: feature for feature in features}
    parents = {row.feature_id: row.parent_id for row in db.query(ServiceHierarchy).all()}
    statuses = {row.feature_id: row.is_active for row in db.query(ServiceStatus).all()}
    key_statuses = module_status.load_statuses(db)
    dependencies_by_key: dict[str, list[str]] = {}
    for row in db.query(ServiceDependency).all():
        dependencies_by_key.setdefault(row.service_key, []).append(row.dependency_key)
    configurations = {row.catalog_key: row for row in db.query(ServiceConfiguration).all()}
    custom_ids = {row.feature_id for row in db.query(ServiceCatalogEntry).all()}

    def status_for(key: str, feature) -> bool:
        return module_status.resolve(key_statuses, key, statuses.get(feature.id) if feature else None)

    modules = []
    canonical_names = {entry[0]: entry[1] for entry in DEFAULT_PLATFORM_FEATURES}
    included = set()
    for module in DEFAULT_TENANT_MODULES:
        feature = by_key.get(str(module.get("permission_key") or "")) or by_key.get(str(module["key"]))
        if feature:
            included.add(feature.id)
        key = str(module["key"])
        modules.append({"id": feature.id if feature else None, "key": key,
                        "name": feature.name if feature and feature.name != canonical_names.get(feature.key, feature.name) else str(module["label"]), "module": feature.module if feature and feature.module and feature.module != "General" else str(module["section"]),
                        "description": feature.description if feature else None,
                        "parent_id": None, "is_active": status_for(key, feature),
                        "feature_key": feature.key if feature else None,
                        "manageable": bool(feature)})
    for feature in sorted(features, key=lambda f: f.name.lower()):
        parent_id = parents.get(feature.id)
        if feature.id in included or (feature.id not in custom_ids and parent_id not in included):
            continue
        modules.append({"id": feature.id, "key": feature.key, "name": feature.name,
                        "module": feature.module, "description": feature.description,
                        "parent_id": parent_id, "is_active": status_for(feature.key, feature),
                        "feature_key": feature.key, "manageable": True})
    # These are the actual tabs in the tenant Dashboard and Settings pages.
    # Most Settings tabs do not have independent platform feature records.
    sections = {
        "dashboard": [
            ("overview", "Overview", None),
            ("customers", "Customers", "dashboard.customers.view"),
            ("leads", "Leads", "dashboard.leads.view"),
            ("tenders", "Tenders", "dashboard.tenders.view"),
            ("emdbg", "EMD / BG", "dashboard.emdbg.view"),
            ("kam360", "KAM 360", "dashboard.kam360.view"),
            ("travel", "Travel", "dashboard.travel.view"),
            ("deals", "Deals", "dashboard.deals.view"),
            ("orders", "Orders & delivery", "dashboard.orders.view"),
            ("finance", "Finance", "dashboard.finance.view"),
            ("login_tracker", "Login Tracker", "dashboard.login_tracker.view"),
        ],
        "settings": [
            ("theme", "Theme & Branding", None),
            ("company", "Company", None),
            ("notifications", "Notifications", None),
            ("security", "Security", None),
            ("approvals", "Approvals", None),
            ("escalation_overrides", "Escalation Overrides", None),
            ("auto_approve", "Auto Approve", None),
        ],
    }
    for parent_key, tabs in sections.items():
        parent = next(item for item in modules if item["key"] == parent_key)
        for tab_key, label, permission_key in tabs:
            feature = by_key.get(permission_key) if permission_key else None
            if feature and any(item["id"] == feature.id for item in modules):
                continue
            key = f"{parent_key}.{tab_key}"
            modules.append({"id": feature.id if feature else None, "key": key,
                            "name": label, "module": parent["module"],
                            "description": feature.description if feature else None,
                            "parent_id": parent["id"], "parent_key": parent_key,
                            "is_active": status_for(key, feature),
                            "feature_key": feature.key if feature else None,
                            "manageable": bool(feature)})
    plan_counts = {feature_id: count for feature_id, count in db.query(PlanFeature.feature_id, func.count(PlanFeature.id)).filter(PlanFeature.enabled == True).group_by(PlanFeature.feature_id).all()}
    tenant_counts = {feature_id: count for feature_id, count in db.query(TenantFeature.feature_id, func.count(TenantFeature.id)).filter(TenantFeature.enabled == True).group_by(TenantFeature.feature_id).all()}
    for item in modules:
        config = configurations.get(item["key"])
        item["dependencies"] = sorted(dependencies_by_key.get(item["key"], []))
        item["configuration_status"] = config.status if config else "ready"
        item["configuration_notes"] = config.notes if config else None
        item["plan_assignments"] = plan_counts.get(item["id"], 0) if item["id"] else 0
        item["tenant_assignments"] = tenant_counts.get(item["id"], 0) if item["id"] else 0
    return modules


@protected_router.get("/services")
def list_services(db: Session = Depends(get_master_db_dep)):
    modules = _build_service_catalog(db)
    db.commit()
    return modules


@protected_router.get("/services/{catalog_key}/tenants")
def list_service_tenants(catalog_key: str, db: Session = Depends(get_master_db_dep)):
    catalog = _build_service_catalog(db)
    item = next((entry for entry in catalog if entry["key"] == catalog_key), None)
    if item is None:
        raise HTTPException(status_code=404, detail="Module not found")
    if item["id"] is None:
        return {"service_key": catalog_key, "tenants": []}
    tenants = (
        db.query(Tenant)
        .join(TenantFeature, TenantFeature.tenant_id == Tenant.id)
        .filter(TenantFeature.feature_id == item["id"], TenantFeature.enabled == True)
        .order_by(Tenant.name.asc())
        .all()
    )
    return {"service_key": catalog_key, "tenants": [
        {"id": tenant.id, "name": tenant.name, "slug": tenant.slug, "subdomain": tenant.subdomain, "status": tenant.status}
        for tenant in tenants
    ]}


class ServiceManagementUpdate(BaseModel):
    dependencies: Optional[list[str]] = None
    configuration_status: Optional[str] = None
    configuration_notes: Optional[str] = None


@protected_router.put("/services/{catalog_key}/management")
def update_service_management(catalog_key: str, data: ServiceManagementUpdate, request: Request, db: Session = Depends(get_master_db_dep)):
    catalog = _build_service_catalog(db)
    by_key = {item["key"]: item for item in catalog}
    item = by_key.get(catalog_key)
    if item is None:
        raise HTTPException(status_code=404, detail="Module not found")
    changes = data.model_dump(exclude_unset=True)
    if "dependencies" in changes:
        dependencies = list(dict.fromkeys(str(key).strip() for key in (changes["dependencies"] or []) if str(key).strip()))
        if catalog_key in dependencies or any(key not in by_key for key in dependencies):
            raise HTTPException(status_code=400, detail="Dependencies must be other modules in the catalog")
        if any(catalog_key in [row.dependency_key for row in db.query(ServiceDependency).filter(ServiceDependency.service_key == dependency).all()] for dependency in dependencies):
            raise HTTPException(status_code=400, detail="A dependency cannot create a circular relationship")
        db.query(ServiceDependency).filter(ServiceDependency.service_key == catalog_key).delete()
        for dependency in dependencies:
            db.add(ServiceDependency(service_key=catalog_key, dependency_key=dependency))
    if "configuration_status" in changes or "configuration_notes" in changes:
        configuration = db.get(ServiceConfiguration, catalog_key)
        if configuration is None:
            configuration = ServiceConfiguration(catalog_key=catalog_key)
            db.add(configuration)
        if "configuration_status" in changes:
            if changes["configuration_status"] not in {"ready", "needs_configuration", "not_applicable"}:
                raise HTTPException(status_code=400, detail="Invalid configuration status")
            configuration.status = changes["configuration_status"]
        if "configuration_notes" in changes:
            configuration.notes = (changes["configuration_notes"] or "").strip() or None
    _write_platform_audit(db, _get_platform_admin(request), "update_service_management", "platform_module", item["id"], catalog_key,
                          f"Updated configuration for {item['name']}", get_request_ip(request), new_data=changes)
    db.commit()
    return next(entry for entry in _build_service_catalog(db) if entry["key"] == catalog_key)


class ServiceStatusUpdate(BaseModel):
    key: str
    is_active: bool


@protected_router.put("/services/status")
def set_service_status(data: ServiceStatusUpdate, request: Request, db: Session = Depends(get_master_db_dep)):
    """Toggle any catalog item â€” module or sub-module, linked or "Not linked" â€” by its key."""
    catalog = _build_service_catalog(db)
    item = next((entry for entry in catalog if entry["key"] == data.key), None)
    if item is None:
        raise HTTPException(status_code=404, detail="Module not found")
    previous = item["is_active"]
    module_status.set_status(db, data.key, data.is_active)
    if item["id"] is not None:
        # Keep the legacy per-feature row in step for anything still reading it.
        legacy = db.get(ServiceStatus, item["id"])
        if legacy is None:
            db.add(ServiceStatus(feature_id=item["id"], is_active=data.is_active))
        else:
            legacy.is_active = data.is_active
    _write_platform_audit(db, _get_platform_admin(request), "update_module_status", "platform_module", item["id"], data.key,
                          f"{'Activated' if data.is_active else 'Deactivated'} {item['name']}", get_request_ip(request),
                          old_data={"is_active": previous}, new_data={"is_active": data.is_active})
    db.commit()
    return {"key": data.key, "is_active": data.is_active}


@protected_router.get("/services/onboarding-visibility")
def service_onboarding_visibility(db: Session = Depends(get_master_db_dep)):
    """Feature keys Tenant Onboarding should hide.

    A sub-module is hidden when it or its parent module is inactive. Only the
    onboarding screen uses this; tenant permissions are not changed.
    """
    catalog = _build_service_catalog(db)
    by_key = {item["key"]: item for item in catalog}
    by_id = {item["id"]: item for item in catalog if item["id"] is not None and not item.get("parent_key")}
    hidden: set[str] = set()
    for item in catalog:
        parent = by_key.get(item.get("parent_key")) if item.get("parent_key") else by_id.get(item.get("parent_id"))
        visible = item["is_active"] and (parent is None or parent["is_active"])
        if not visible and item.get("feature_key"):
            hidden.add(item["feature_key"])
    db.commit()
    return {
        "hidden_feature_keys": sorted(hidden),
        "inactive_keys": sorted(item["key"] for item in catalog if not item["is_active"]),
    }

@protected_router.post("/services", status_code=201)
def create_service(data: ServiceCreate, db: Session = Depends(get_master_db_dep)):
    import re
    key = data.key.strip().lower()
    name = data.name.strip()
    if not name or not re.fullmatch(r"[a-z0-9_]{1,100}", key):
        raise HTTPException(status_code=400, detail="Name and a key using lowercase letters, numbers or underscores are required")
    if len(name) > 200 or len((data.module or "").strip()) > 100:
        raise HTTPException(status_code=400, detail="Name or category is too long")
    if db.query(Feature).filter(Feature.key == key).first():
        raise HTTPException(status_code=400, detail="Feature key already exists")
    if data.parent_id is not None:
        parent = db.get(Feature, data.parent_id)
        if not parent or db.get(ServiceHierarchy, data.parent_id):
            raise HTTPException(status_code=400, detail="Choose an existing top-level service")
    feature = Feature(key=key, name=name, module=(data.module or "General").strip() or "General", description=(data.description or "").strip() or None)
    db.add(feature)
    db.flush()
    db.add(ServiceCatalogEntry(feature_id=feature.id))
    if data.parent_id is not None:
        db.add(ServiceHierarchy(feature_id=feature.id, parent_id=data.parent_id))
    db.commit()
    return {"id": feature.id, "key": feature.key, "name": feature.name, "module": feature.module,
            "description": feature.description, "parent_id": data.parent_id}


class ServiceUpdate(BaseModel):
    name: Optional[str] = None
    module: Optional[str] = None
    description: Optional[str] = None
    is_active: Optional[bool] = None


@protected_router.patch("/services/{feature_id}")
def update_service(feature_id: int, data: ServiceUpdate, db: Session = Depends(get_master_db_dep)):
    feature = db.get(Feature, feature_id)
    if not feature:
        raise HTTPException(status_code=404, detail="Service not found")
    changes = data.model_dump(exclude_unset=True)
    if "name" in changes:
        name = (changes["name"] or "").strip()
        if not name or len(name) > 200:
            raise HTTPException(status_code=400, detail="A valid service name is required")
        feature.name = name
    if "module" in changes:
        module = (changes["module"] or "").strip()
        if len(module) > 100:
            raise HTTPException(status_code=400, detail="Category is too long")
        feature.module = module or "General"
    if "description" in changes:
        feature.description = (changes["description"] or "").strip() or None
    if changes.get("is_active") is not None:
        status = db.get(ServiceStatus, feature_id)
        if status is None:
            status = ServiceStatus(feature_id=feature_id)
            db.add(status)
        status.is_active = changes["is_active"]
        # Key status takes precedence, so update the catalog keys linked to this feature too.
        for item in _build_service_catalog(db):
            if item["id"] == feature_id:
                module_status.set_status(db, item["key"], changes["is_active"])
    db.commit()
    return {"message": "Service updated"}


@protected_router.delete("/services/{feature_id}")
def delete_service(feature_id: int, request: Request, db: Session = Depends(get_master_db_dep)):
    """Soft-delete a custom service by deactivating its catalog entry."""
    feature = db.get(Feature, feature_id)
    if not feature:
        raise HTTPException(status_code=404, detail="Service not found")
    catalog = _build_service_catalog(db)
    entries = [item for item in catalog if item["id"] == feature_id]
    if not entries:
        raise HTTPException(status_code=409, detail="Service is not available in the module catalog")
    for item in entries:
        module_status.set_status(db, item["key"], False)
    status = db.get(ServiceStatus, feature_id)
    if status is None:
        db.add(ServiceStatus(feature_id=feature_id, is_active=False))
    else:
        status.is_active = False
    _write_platform_audit(db, _get_platform_admin(request), "deactivate_service", "platform_module", feature_id, feature.key,
                          f"Deactivated {feature.name}", get_request_ip(request), new_data={"is_active": False})
    db.commit()
    return {"message": "Service deactivated"}

@protected_router.get("/plans/{plan_id}/features", response_model=PlanFeatureResponse)
def get_plan_features(plan_id: int, db: Session = Depends(get_master_db_dep)):
    plan = db.query(Plan).filter(Plan.id == plan_id).first()
    if not plan:
        raise HTTPException(status_code=404, detail="Plan not found")
    rows = db.query(PlanFeature).filter(
        PlanFeature.plan_id == plan_id, PlanFeature.enabled == True,
    ).all()
    return {"plan_id": plan_id, "feature_ids": [row.feature_id for row in rows]}


@protected_router.put("/plans/{plan_id}/features", response_model=PlanFeatureResponse)
def update_plan_features(
    plan_id: int,
    data: PlanFeatureUpdate,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    admin = _get_platform_admin(request)
    ip = get_request_ip(request)
    plan = db.query(Plan).filter(Plan.id == plan_id).first()
    if not plan:
        raise HTTPException(status_code=404, detail="Plan not found")

    feature_ids = sorted(set(data.feature_ids or []))
    if feature_ids:
        existing_count = db.query(Feature).filter(Feature.id.in_(feature_ids)).count()
        if existing_count != len(feature_ids):
            raise HTTPException(status_code=400, detail="One or more feature IDs are invalid")

    db.query(PlanFeature).filter(PlanFeature.plan_id == plan_id).delete()
    for feature_id in feature_ids:
        db.add(PlanFeature(plan_id=plan_id, feature_id=feature_id, enabled=True))

    _write_platform_audit(
        db=db, admin=admin, action="update_plan_features", entity_type="plan",
        entity_id=plan_id, entity_name=plan.name,
        description=f"Feature matrix updated for plan '{plan.name}': {len(feature_ids)} features",
        ip=ip, new_data={"feature_ids": feature_ids},
    )
    db.commit()
    return {"plan_id": plan_id, "feature_ids": feature_ids}


