@protected_router.get("/audit-logs")
def list_platform_audit_logs(
    request: Request,
    limit: int = 200,
    entity_type: Optional[str] = None,
    action: Optional[str] = None,
    page: Optional[int] = None,
    page_size: int = 25,
    search: str = "",
    date_from: Optional[date] = None,
    date_to: Optional[date] = None,
    db: Session = Depends(get_master_db_dep),
):
    query = db.query(PlatformAuditLog, SuperAdmin).outerjoin(
        SuperAdmin, PlatformAuditLog.super_admin_id == SuperAdmin.id
    ).order_by(PlatformAuditLog.created_at.desc())
    allowed = access_control.scoped_tenant_ids(request)
    if allowed is not None:   # tenant-scoped staff: entries about their tenants only
        query = query.filter(PlatformAuditLog.entity_type == "tenant", PlatformAuditLog.entity_id.in_(allowed or [0]))

    if entity_type:
        query = query.filter(PlatformAuditLog.entity_type == entity_type)
    if action:
        query = query.filter(PlatformAuditLog.action == action)

    if search.strip():
        term = search.strip().replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        query = query.filter(or_(*[field.ilike(f"%{term}%", escape="\\") for field in (
            PlatformAuditLog.action, PlatformAuditLog.entity_type, PlatformAuditLog.entity_name,
            PlatformAuditLog.description, PlatformAuditLog.ip_address, SuperAdmin.full_name, SuperAdmin.username,
        )]))
    if date_from:
        query = query.filter(PlatformAuditLog.created_at >= datetime.combine(date_from, time.min))
    if date_to:
        query = query.filter(PlatformAuditLog.created_at <= datetime.combine(date_to, time.max))
    total = query.count() if page is not None else None
    if page is not None:
        if page < 1 or page_size < 0 or page_size > 100:
            raise HTTPException(status_code=422, detail="Invalid pagination")
        query = query.order_by(PlatformAuditLog.id.desc())
        if page_size:
            query = query.offset((page - 1) * page_size).limit(page_size)
    else:
        query = query.limit(limit)
    rows = query.all()
    items = [
        {
            "id": log.id,
            "action": log.action,
            "entity_type": log.entity_type,
            "entity_id": log.entity_id,
            "entity_name": log.entity_name,
            "description": log.description,
            "ip_address": log.ip_address,
            "performed_by": sa.full_name if sa else "System",
            "performed_by_username": sa.username if sa else None,
            "old_data": audit_trail.redact(log.old_data),
            "new_data": audit_trail.redact(log.new_data),
            "created_at": log.created_at.isoformat() if log.created_at else None,
        }
        for log, sa in rows
    ]
    if page is None:
        return items
    return {
        "items": items, "total": total,
        "entity_types": [r[0] for r in db.query(PlatformAuditLog.entity_type).distinct().order_by(PlatformAuditLog.entity_type).all() if r[0]],
        "actions": [r[0] for r in db.query(PlatformAuditLog.action).distinct().order_by(PlatformAuditLog.action).all() if r[0]],
    }


