@protected_router.get("/super-admins", response_model=list[SuperAdminResponse])
def list_super_admins(db: Session = Depends(get_master_db_dep)):
    return db.query(SuperAdmin).order_by(SuperAdmin.created_at.asc()).all()


@protected_router.post("/super-admins", response_model=SuperAdminResponse, status_code=201)
def create_super_admin(
    data: SuperAdminCreate,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    admin = _get_platform_admin(request)
    ip = get_request_ip(request)

    if db.query(SuperAdmin).filter(SuperAdmin.username == data.username).first():
        raise HTTPException(status_code=400, detail="Username already taken")
    if db.query(SuperAdmin).filter(SuperAdmin.email == data.email).first():
        raise HTTPException(status_code=400, detail="Email already registered")
    auditor_role = _role_or_404(db, role_key="read_only_auditor")
    _require_role_within_caller(request, auditor_role)
    policy_error = _password_policy_error(db, None, data.password)
    if policy_error:
        raise HTTPException(status_code=400, detail=policy_error)

    new_admin = SuperAdmin(
        username=data.username,
        email=data.email,
        full_name=data.full_name,
        hashed_password=hash_password(data.password),
        is_active=True,
    )
    db.add(new_admin)
    db.flush()
    _record_password(db, new_admin)
    db.add(PlatformStaffAccess(admin_id=new_admin.id, role_id=auditor_role.id, scope="all"))
    if _platform_setting(db, "platform_force_first_login"):
        db.add(PlatformSetting(key=f"platform_first_change_{new_admin.id}", value_bool=True))
    _write_platform_audit(
        db=db, admin=admin, action="create_super_admin", entity_type="super_admin",
        entity_id=new_admin.id, entity_name=new_admin.username,
        description=f"Super admin '{new_admin.username}' created",
        ip=ip, new_data={"username": new_admin.username, "email": new_admin.email},
    )
    db.commit()
    db.refresh(new_admin)
    return new_admin


@protected_router.put("/super-admins/{admin_id}", response_model=SuperAdminResponse)
def update_super_admin(
    admin_id: int,
    data: SuperAdminUpdate,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    current_admin = _get_platform_admin(request)
    ip = get_request_ip(request)

    target = db.query(SuperAdmin).filter(SuperAdmin.id == admin_id).first()
    if not target:
        raise HTTPException(status_code=404, detail="Super admin not found")
    if not current_admin or current_admin.id != target.id:
        _require_can_manage_staff(db, request, target)

    updates = data.model_dump(exclude_unset=True)
    if "password" in updates:
        policy_error = _password_policy_error(db, target, updates["password"])
        if policy_error:
            raise HTTPException(status_code=400, detail=policy_error)
        target.hashed_password = hash_password(updates.pop("password"))
        _record_password(db, target)
    for field, val in updates.items():
        setattr(target, field, val)

    _write_platform_audit(
        db=db, admin=current_admin, action="update_super_admin", entity_type="super_admin",
        entity_id=target.id, entity_name=target.username,
        description=f"Super admin '{target.username}' updated",
        ip=ip, new_data={k: v for k, v in updates.items() if k != "password"},
    )
    db.commit()
    db.refresh(target)
    return target


@protected_router.post("/super-admins/{admin_id}/deactivate")
def deactivate_super_admin(
    admin_id: int,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    current_admin = _get_platform_admin(request)
    ip = get_request_ip(request)

    if current_admin and current_admin.id == admin_id:
        raise HTTPException(status_code=400, detail="Cannot deactivate your own account")

    target = db.query(SuperAdmin).filter(SuperAdmin.id == admin_id).first()
    if not target:
        raise HTTPException(status_code=404, detail="Super admin not found")
    if not target.is_active:
        raise HTTPException(status_code=400, detail="This account is already inactive")
    _require_can_manage_staff(db, request, target)
    _guard_staff_access_loss(db, target)
    gate = _four_eyes_gate(db, request, "deactivate_super_admin", "super_admin", target.id, target.username,
                           f"Deactivate staff account '{target.full_name or target.username}'", {"admin_id": target.id})
    if gate:
        return gate

    target.is_active = False
    _write_platform_audit(
        db=db, admin=current_admin, action="deactivate_super_admin", entity_type="super_admin",
        entity_id=target.id, entity_name=target.username,
        description=f"Super admin '{target.username}' deactivated",
        ip=ip,
    )
    db.commit()
    return {"message": "Super admin deactivated"}


@protected_router.post("/super-admins/{admin_id}/activate")
def activate_super_admin(
    admin_id: int,
    request: Request,
    db: Session = Depends(get_master_db_dep),
):
    current_admin = _get_platform_admin(request)
    ip = get_request_ip(request)

    target = db.query(SuperAdmin).filter(SuperAdmin.id == admin_id).first()
    if not target:
        raise HTTPException(status_code=404, detail="Super admin not found")
    _require_can_manage_staff(db, request, target)

    target.is_active = True
    _write_platform_audit(
        db=db, admin=current_admin, action="activate_super_admin", entity_type="super_admin",
        entity_id=target.id, entity_name=target.username,
        description=f"Super admin '{target.username}' activated",
        ip=ip,
    )
    db.commit()
    return {"message": "Super admin activated"}


