def dashboard_recent_tenants(db: Session = Depends(get_master_db_dep)):
    """Fast dashboard feed: avoids cross-tenant storage and user-count work."""
    tenants = db.query(Tenant).order_by(Tenant.created_at.desc()).limit(8).all()
    return [TenantResponse.model_validate(tenant) for tenant in tenants]

@protected_router.get("/stats")
def platform_stats(db: Session = Depends(get_master_db_dep)):
    total = db.query(Tenant).count()
    active = db.query(Tenant).filter(Tenant.status == "active").count()
    trial = db.query(Tenant).filter(Tenant.status == "trial").count()
    suspended = db.query(Tenant).filter(Tenant.status == "suspended").count()
    cancelled = db.query(Tenant).filter(Tenant.status == "cancelled").count()
    return {
        "total_tenants": total,
        "active_tenants": active,
        "trial_tenants": trial,
        "suspended_tenants": suspended,
        "cancelled_tenants": cancelled,
        "total_plans": db.query(Plan).count(),
        "total_super_admins": db.query(SuperAdmin).filter(SuperAdmin.is_active == True).count(),
    }


